style.css:
@font-face {
    font-family: "Kids Word";
    src: url("https://raw.githubusercontent.com/moriezvalexcia-code/roblox-font/main/Kids%20Word.otf") format("opentype");
    font-weight: normal;
    font-style: normal;
}

html,
body,
div,
span,
p,
a,
button,
input,
textarea,
label,
h1,
h2,
h3,
h4,
h5,
h6,
text,
[class*="text"],
[class*="Text"],
[class*="label"],
[class*="Label"],
[class*="button"],
[class*="Button"] {
    font-family: "Kids Word" !important;
}
